// ---- 09_Lib/hash.mjs ----------------------------------------------------
// n8n Code nodes run in a sandbox with no `crypto`; neither the module nor the
// global. The hash travels with the workflow. Correctness is held by lib.test.mjs, 
// which checks this against node:crypto over a corpus.

const K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

const utf8Bytes = (str) => {
  const out = [];
  for (const ch of String(str)) {
    let cp = ch.codePointAt(0);
    if (cp < 0x80) out.push(cp);
    else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 63));
    else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
    else out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
  }
  return out;
};

const rotr = (x, n) => (x >>> n) | (x << (32 - n));

function sha256(input) {
  const bytes = utf8Bytes(input);
  const bitLen = bytes.length * 8;

  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  // Length is a 64-bit big-endian count; the high word is written from a float
  // divide because bitwise ops in JS are 32-bit.
  const hi = Math.floor(bitLen / 0x100000000);
  for (let i = 3; i >= 0; i--) bytes.push((hi >>> (i * 8)) & 0xff);
  for (let i = 3; i >= 0; i--) bytes.push((bitLen >>> (i * 8)) & 0xff);

  let [h0, h1, h2, h3, h4, h5, h6, h7] =
    [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];

  const w = new Array(64);
  for (let offset = 0; offset < bytes.length; offset += 64) {
    for (let i = 0; i < 16; i++) {
      const j = offset + i * 4;
      w[i] = (bytes[j] << 24) | (bytes[j + 1] << 16) | (bytes[j + 2] << 8) | bytes[j + 3];
    }
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
    }

    let [a, b, c, d, e, f, g, h] = [h0, h1, h2, h3, h4, h5, h6, h7];
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[i] + w[i]) | 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0;
      d = c; c = b; b = a; a = (t1 + t2) | 0;
    }

    h0 = (h0 + a) | 0; h1 = (h1 + b) | 0; h2 = (h2 + c) | 0; h3 = (h3 + d) | 0;
    h4 = (h4 + e) | 0; h5 = (h5 + f) | 0; h6 = (h6 + g) | 0; h7 = (h7 + h) | 0;
  }

  return [h0, h1, h2, h3, h4, h5, h6, h7]
    .map((n) => (n >>> 0).toString(16).padStart(8, '0'))
    .join('');
}
// ---- 09_Lib/ids.mjs -----------------------------------------------------
const CROCKFORD = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';

// Math.random is deliberate. A lead_id needs to be unique, not unguessable, and the
// Code node sandbox has no CSPRNG. Anything that must be unpredictable; the VIP
// approval callback token, is generated by Postgres with gen_random_uuid() instead,
// which is where secret material belongs anyway.
const randomBytes = (n) => Array.from({ length: n }, () => Math.floor(Math.random() * 256));

// ULID rather than UUIDv4: lexicographically sortable, so it doubles as a coarse
// arrival order and gives dedup a stable tie-break for which record is the master.
function ulid(now = Date.now(), rand = randomBytes(10)) {
  let ts = '';
  let t = now;
  for (let i = 9; i >= 0; i--) { ts = CROCKFORD[t % 32] + ts; t = Math.floor(t / 32); }

  let bits = 0, value = 0, out = '';
  for (const byte of rand) {
    value = (value << 8) | byte;
    bits += 8;
    while (bits >= 5) { out += CROCKFORD[(value >>> (bits - 5)) & 31]; bits -= 5; }
  }
  return (ts + out).slice(0, 26);
}

// Key derivation depends on this being stable for equal content, so key order
// must not leak into the hash.
function canonicalJson(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value ?? null);
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  const keys = Object.keys(value).sort();
  return `{${keys.map((k) => `${JSON.stringify(k)}:${canonicalJson(value[k])}`).join(',')}}`;
}
// ---- 09_Lib/normalize.mjs -----------------------------------------------
// Normalisation is lossy, so nothing here mutates the original value — callers keep
// the raw field alongside the normalised one. Edge case 2 (same number, two formats)
// is solved by comparing normalised values; auditing it needs the raw ones.

// Enough of a dial plan to be correct for the regions this demo uses. Production
// swaps this for libphonenumber-js, which knows about number types, carrier
// prefixes and the many places where national significant number length varies.
const DIAL_PLAN = {
  AE: { cc: '971', nsn: [9] },
  GB: { cc: '44',  nsn: [10] },
  US: { cc: '1',   nsn: [10] },
  DE: { cc: '49',  nsn: [10, 11] },
  JP: { cc: '81',  nsn: [9, 10] },
  EG: { cc: '20',  nsn: [10] },
};

const CC_LOOKUP = Object.entries(DIAL_PLAN)
  .map(([region, { cc }]) => ({ region, cc }))
  .sort((a, b) => b.cc.length - a.cc.length);

function normalizePhone(raw, defaultRegion = 'AE') {
  const result = { raw: raw ?? null, e164: null, valid: false, reason: null, region: null };
  if (!raw) { result.reason = 'missing'; return result; }

  let s = String(raw).trim();
  const hadPlus = s.startsWith('+') || s.startsWith('00');
  let digits = s.replace(/[^\d]/g, '');

  if (s.startsWith('00')) digits = digits.slice(2);

  if (!digits) { result.reason = 'no_digits'; return result; }

  if (hadPlus) {
    const match = CC_LOOKUP.find(({ cc }) => digits.startsWith(cc));
    if (!match) { result.reason = 'unknown_country_code'; return result; }
    result.region = match.region;
  } else {
    const plan = DIAL_PLAN[defaultRegion];
    if (!plan) { result.reason = 'unknown_default_region'; return result; }
    // Trunk prefix: a leading 0 on a national number is a dialling convention,
    // not part of the number.
    if (digits.startsWith('0')) digits = digits.replace(/^0+/, '');
    // Some sources submit the country code without a plus. Treat it as already
    // international when the remainder is a plausible national number.
    if (!digits.startsWith(plan.cc) || !plan.nsn.includes(digits.length - plan.cc.length)) {
      digits = plan.cc + digits;
    }
    result.region = defaultRegion;
  }

  const plan = DIAL_PLAN[result.region];
  const nsnLength = digits.length - plan.cc.length;
  if (!plan.nsn.includes(nsnLength)) {
    result.reason = `bad_length_for_${result.region}`;
    result.e164 = `+${digits}`;
    return result;
  }

  result.e164 = `+${digits}`;
  result.valid = true;
  return result;
}

// Casing and surrounding whitespace are never meaningful in an address.
function normalizeEmail(raw) {
  const result = { raw: raw ?? null, normalized: null, valid: false, localPart: null, domain: null };
  if (!raw) return result;

  const s = String(raw).trim().toLowerCase();
  const at = s.lastIndexOf('@');
  if (at < 1 || at === s.length - 1) return result;

  const [local, domain] = [s.slice(0, at), s.slice(at + 1)];
  if (!/^[^\s@]+$/.test(local)) return result;
  if (!/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(domain)) return result;

  result.normalized = `${local}@${domain}`;
  result.localPart = local;
  result.domain = domain;
  result.valid = true;
  return result;
}

// Gmail-style dot and +tag stripping is a *dedup feature only*. It must never
// replace the address we actually send to — some providers treat those as distinct.
const DOT_INSENSITIVE = new Set(['gmail.com', 'googlemail.com']);

function emailDedupKey(email) {
  const { valid, localPart, domain } = normalizeEmail(email);
  if (!valid) return null;
  let local = localPart.split('+')[0];
  if (DOT_INSENSITIVE.has(domain)) local = local.replace(/\./g, '');
  return `${local}@${domain}`;
}

const HONORIFICS = /^(mr|mrs|ms|miss|dr|prof|eng|sir|madam)\.?\s+/i;

function normalizeName(raw) {
  if (!raw) return { raw: raw ?? null, normalized: null, tokens: [] };
  const normalized = String(raw)
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')   // strip combining accents left by NFKD
    .replace(HONORIFICS, '')
    .replace(/[^\p{L}\p{N}\s'-]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
  return { raw, normalized: normalized || null, tokens: normalized ? normalized.split(' ') : [] };
}

const COMPANY_NOISE = /\b(inc|llc|ltd|limited|gmbh|bv|sa|sas|plc|co|corp|corporation|company|group|holdings?|fz-?llc|llp)\b\.?/g;

function normalizeCompany(raw) {
  if (!raw) return null;
  const s = String(raw).toLowerCase()
    .replace(/[^\p{L}\p{N}\s&-]/gu, ' ')
    .replace(COMPANY_NOISE, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return s || null;
}
// ---- 09_Lib/idempotency.mjs ---------------------------------------------
// A key names an *effect*, not an attempt. Two tries at the same effect collide;
// two different effects never do. Nothing that varies between retries may appear
// here — no execution id, no timestamp, no attempt counter — because replay safety
// (edge case 14) is a consequence of that purity rather than a separate mechanism.

const KEY_VERSION = 'v1';

function effectKey({ domain, entityType = 'lead', entityId, occurrence = '1' }) {
  if (!domain || !entityId) throw new Error('effectKey needs domain and entityId');
  for (const part of [domain, entityType, entityId, occurrence]) {
    if (String(part).includes(':')) throw new Error(`key part "${part}" must not contain ':'`);
  }
  return `${KEY_VERSION}:${domain}:${entityType}:${entityId}:${occurrence}`;
}

function parseEffectKey(key) {
  const [version, domain, entityType, entityId, ...rest] = String(key).split(':');
  return { version, domain, entityType, entityId, occurrence: rest.join(':') };
}

// The link the whole chain hangs on. If a redelivered webhook minted a fresh
// lead_id, every downstream key would differ and every effect would fire twice.
// Prefer the provider's own event id; fall back to a content hash.
function sourceEventKey({ source, providerEventId, payload }) {
  if (!source) throw new Error('sourceEventKey needs a source');
  if (providerEventId) return `${source}:id:${providerEventId}`;
  return `${source}:sha256:${sha256(canonicalJson(payload ?? {}))}`;
}

// Detects a key reused with genuinely different content, which is a bug in the
// caller rather than a retry, and should be surfaced instead of silently deduped.
const requestFingerprint = (body) => sha256(canonicalJson(body ?? {}));

// Full jitter. Decorrelates retry storms harder than equal jitter, and the worst
// case is an early retry rather than a synchronised thundering herd.
function nextBackoffMs(attempt, { baseMs = 2000, capMs = 900_000, random = Math.random } = {}) {
  const ceiling = Math.min(baseMs * 2 ** attempt, capMs);
  return Math.floor(random() * ceiling);
}

const RETRYABLE_STATUS = new Set([408, 425, 429, 500, 502, 503, 504]);
const TRANSPORT_ERRORS = /ECONNRESET|ETIMEDOUT|ECONNREFUSED|EAI_AGAIN|ENOTFOUND|socket hang up|aborted/i;

// Classify before scheduling. Burning five attempts on a 401 is slow and useless,
// and brief section I calls out missing credentials as its own case.
function classifyFailure({ status, code, message } = {}) {
  if (status === 401 || status === 403) {
    return { retryable: false, reason: 'auth', detail: 'credentials rejected — retrying cannot help' };
  }
  if (status && RETRYABLE_STATUS.has(status)) {
    return { retryable: true, reason: status === 429 ? 'rate_limited' : 'transient_server' };
  }
  if (status && status >= 400 && status < 500) {
    return { retryable: false, reason: 'client_error', detail: `permanent ${status}` };
  }
  if (TRANSPORT_ERRORS.test(`${code ?? ''} ${message ?? ''}`)) {
    return { retryable: true, reason: 'transport' };
  }
  if (status && status >= 500) return { retryable: true, reason: 'transient_server' };
  return { retryable: false, reason: 'unknown', detail: message ?? null };
}

// A 429 that tells us when to come back beats our own guess.
function retryAfterMs(headers = {}) {
  const raw = headers['retry-after'] ?? headers['Retry-After'];
  if (!raw) return null;
  const seconds = Number(raw);
  if (Number.isFinite(seconds)) return seconds * 1000;
  const at = Date.parse(raw);
  return Number.isFinite(at) ? Math.max(0, at - Date.now()) : null;
}
// ---- 09_Lib/csv.mjs -----------------------------------------------------
// Edge case 13 is the whole reason this exists: one corrupted row in an otherwise
// valid batch must not take the batch down with it. So parsing is per-record and
// every record carries its own verdict rather than throwing.

function splitRecords(text) {
  const records = [];
  let field = '';
  let record = [];
  let inQuotes = false;
  let sawQuote = false;
  let malformed = false;
  let raw = '';

  const pushField = () => { record.push(field); field = ''; };
  const pushRecord = () => {
    if (record.length || field.length) pushField();
    if (record.length) records.push({ values: record, raw: raw.replace(/\r?\n$/, ''), malformed });
    record = []; raw = ''; malformed = false; sawQuote = false;
  };

  const src = String(text ?? '').replace(/^﻿/, '');

  for (let i = 0; i < src.length; i++) {
    const ch = src[i];
    raw += ch;

    if (inQuotes) {
      if (ch === '"') {
        if (src[i + 1] === '"') { field += '"'; raw += src[++i]; }
        else inQuotes = false;
      } else field += ch;
      continue;
    }

    if (ch === '"') {
      // A quote that opens mid-field is not valid CSV. Take the text literally and
      // flag the record rather than letting the quote swallow everything after it.
      if (field.length > 0) { malformed = true; field += ch; }
      else { inQuotes = true; sawQuote = true; }
    } else if (ch === ',') pushField();
    else if (ch === '\n') pushRecord();
    else if (ch !== '\r') field += ch;
  }

  // Unterminated quote at end of input: the record is broken, and saying so beats
  // silently returning a field containing the rest of the file.
  if (inQuotes) malformed = true;
  if (field.length || record.length) pushRecord();

  void sawQuote;
  return records;
}

function parseCsv(text) {
  const records = splitRecords(text);
  if (!records.length) return { header: [], rows: [], error: 'empty input' };

  const header = records[0].values.map((h) => h.trim());
  const rows = records.slice(1).map((rec, i) => {
    const line = i + 2;   // 1-based, and the header occupies line 1

    if (rec.malformed) {
      return { line, ok: false, error: 'malformed_quoting', raw: rec.raw, values: null };
    }
    if (rec.values.length !== header.length) {
      return {
        line, ok: false, error: 'column_count_mismatch', raw: rec.raw, values: null,
        detail: `expected ${header.length} columns, found ${rec.values.length}`,
      };
    }

    const obj = {};
    header.forEach((h, idx) => { obj[h] = rec.values[idx].trim(); });
    return { line, ok: true, values: obj, raw: rec.raw };
  });

  return { header, rows };
}
// ---- 09_Lib/validate.mjs ------------------------------------------------
// Validation sorts leads into "usable now" and "needs a human or a follow-up
// question". It never drops one silently — brief section B is explicit that
// incomplete data goes down a Data Completion path rather than into a void.

const SOURCE_FIELD_MAP = {
  website: {
    full_name: ['name', 'full_name', 'fullName'],
    email_raw: ['email', 'email_address'],
    phone_raw: ['phone', 'mobile', 'phone_number'],
    company: ['company', 'organisation', 'organization'],
    service_interest: ['service', 'service_interest', 'interest'],
    free_text_need: ['message', 'notes', 'need', 'comments'],
    country: ['country'],
    budget_band: ['budget', 'budget_band'],
    timeline: ['timeline', 'timeframe'],
    consent: ['consent', 'marketing_consent', 'opt_in'],
  },
  whatsapp: {
    full_name: ['profile_name', 'contact_name', 'name'],
    phone_raw: ['wa_id', 'from', 'phone'],
    free_text_need: ['text', 'body', 'message'],
    email_raw: ['email'],
    company: ['company'],
    service_interest: ['service_interest', 'service'],
    country: ['country'],
    budget_band: ['budget_band'],
    timeline: ['timeline'],
    consent: ['consent', 'opt_in'],
  },
  csv: {
    full_name: ['name', 'full_name', 'Full Name'],
    email_raw: ['email', 'Email'],
    phone_raw: ['phone', 'Phone', 'mobile'],
    company: ['company', 'Company'],
    service_interest: ['service', 'Service', 'service_interest'],
    free_text_need: ['notes', 'Notes', 'need'],
    country: ['country', 'Country'],
    budget_band: ['budget', 'budget_band'],
    timeline: ['timeline'],
    consent: ['consent', 'Consent'],
  },
};

const firstPresent = (payload, keys) => {
  for (const k of keys) {
    const v = payload?.[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return null;
};

const CONSENT_TRUE = new Set(['true', 'yes', 'y', '1', 'granted', 'opt_in', 'opted_in', 'on']);
const CONSENT_FALSE = new Set(['false', 'no', 'n', '0', 'denied', 'opt_out', 'opted_out', 'off']);

function toCanonical({ source, payload, defaultRegion = 'AE', receivedAt = null }) {
  const map = SOURCE_FIELD_MAP[source];
  if (!map) throw new Error(`no field map for source "${source}"`);

  const picked = {};
  for (const [field, keys] of Object.entries(map)) picked[field] = firstPresent(payload, keys);

  const phone = normalizePhone(picked.phone_raw, defaultRegion);
  const email = normalizeEmail(picked.email_raw);
  const name = normalizeName(picked.full_name);

  const rawConsent = String(picked.consent ?? '').toLowerCase();
  let consent_status = 'unknown';
  if (CONSENT_TRUE.has(rawConsent)) consent_status = 'granted';
  else if (CONSENT_FALSE.has(rawConsent)) consent_status = 'denied';

  // WhatsApp inbound is an inbound contact from the customer, which is consent to
  // reply on that channel — but not consent to market. Recorded as such rather
  // than assumed either way.
  if (consent_status === 'unknown' && source === 'whatsapp') consent_status = 'granted';

  return {
    source,
    received_at: receivedAt,
    full_name: picked.full_name,
    name_normalized: name.normalized,
    phone_raw: picked.phone_raw,
    phone_e164: phone.e164,
    phone_valid: phone.valid,
    email_raw: picked.email_raw,
    email_normalized: email.normalized,
    email_valid: email.valid,
    company: picked.company,
    company_normalized: normalizeCompany(picked.company),
    service_interest: picked.service_interest,
    free_text_need: picked.free_text_need,
    country: picked.country,
    budget_band: picked.budget_band,
    timeline: picked.timeline,
    consent_status,
    consent_source: source,
    channels_allowed: consent_status === 'granted'
      ? [phone.valid ? 'whatsapp' : null, email.valid ? 'email' : null].filter(Boolean)
      : [],
    _normalization: { phone_reason: phone.reason, phone_region: phone.region },
  };
}

function validate(lead) {
  const errors = [];
  const warnings = [];

  if (!lead.full_name) errors.push({ field: 'full_name', code: 'missing' });
  if (!lead.phone_valid && !lead.email_valid) {
    errors.push({ field: 'contact', code: 'no_reachable_channel',
      detail: 'neither a valid phone nor a valid email was supplied' });
  }
  if (lead.phone_raw && !lead.phone_valid) {
    warnings.push({ field: 'phone_raw', code: 'unparseable', detail: lead._normalization?.phone_reason });
  }
  if (lead.email_raw && !lead.email_valid) warnings.push({ field: 'email_raw', code: 'unparseable' });
  if (!lead.service_interest) warnings.push({ field: 'service_interest', code: 'missing' });
  if (lead.consent_status === 'denied') {
    warnings.push({ field: 'consent_status', code: 'denied', detail: 'no outbound channel permitted' });
  }
  if (lead.consent_status === 'unknown') warnings.push({ field: 'consent_status', code: 'unknown' });

  return {
    ok: errors.length === 0,
    errors,
    warnings,
    // Only a hard error diverts the lead. Warnings travel with it so a human can
    // see what was thin without the pipeline stalling on it.
    disposition: errors.length ? 'data_completion' : null,
    reason: errors.length ? errors.map((e) => `${e.field}:${e.code}`).join(', ') : null,
  };
}
// ---- 09_Lib/scoring.mjs -------------------------------------------------
// Deterministic only. The AI classification never feeds this — a score that depends
// on a non-deterministic model cannot be reproduced, explained after the fact, or
// regression tested. Disagreement between the two is handled as a routing signal.

const SCORE_MODEL_VERSION = 'v1';

const TARGET_INDUSTRIES = { manufacturing: 10, logistics: 10, healthcare: 10, consulting: 4, retail: 4 };
const SERVICE_POINTS = { implementation: 15, consulting: 12, training: 6, support: 4 };
const TIMELINE_POINTS = { immediate: 15, this_quarter: 10, six_months: 5, exploring: 0 };
const BUDGET_POINTS = { '>1m': 20, '500k-1m': 16, '100k-500k': 12, '50k-100k': 8, '10k-50k': 4, '<10k': 0 };
const REVENUE_FALLBACK = { '500m-1b': 12, '100m-500m': 10, '50m-100m': 8, '10m-50m': 6, '1m-10m': 4, '<1m': 2 };
const SERVED_REGIONS = new Set(['EMEA', 'MEA', 'APAC', 'AMER']);

function headcountPoints(size) {
  if (!Number.isFinite(size)) return [0, 'no headcount data'];
  if (size >= 1000) return [20, `${size} staff — enterprise`];
  if (size >= 250) return [15, `${size} staff — upper mid-market`];
  if (size >= 50) return [10, `${size} staff — mid-market`];
  if (size >= 10) return [5, `${size} staff — small business`];
  return [0, `${size} staff — micro business`];
}

function scoreLead(lead) {
  const enriched = lead.enrichment?.data ?? {};
  const rules = [];
  const add = (rule_id, points, reason) => rules.push({ rule_id, points, reason });

  const [sizePts, sizeReason] = headcountPoints(Number(enriched.company_size));
  add('company_size', sizePts, sizeReason);

  const industry = String(enriched.industry ?? '').toLowerCase();
  add('industry_fit', TARGET_INDUSTRIES[industry] ?? 0,
    industry ? `industry ${industry}` : 'industry unknown');

  const service = String(lead.service_interest ?? '').toLowerCase();
  add('service_interest', SERVICE_POINTS[service] ?? 0,
    service ? `interested in ${service}` : 'no service interest given');

  // Self-reported budget is the better signal when present; company revenue is a
  // proxy, so it is only consulted when the lead did not tell us.
  const budget = String(lead.budget_band ?? '').toLowerCase();
  if (budget && budget in BUDGET_POINTS) {
    add('budget_band', BUDGET_POINTS[budget], `stated budget ${budget}`);
  } else {
    const rev = String(enriched.revenue_band ?? '');
    add('budget_band', REVENUE_FALLBACK[rev] ?? 0,
      rev ? `no stated budget; revenue band ${rev}` : 'no budget or revenue signal');
  }

  const timeline = String(lead.timeline ?? '').toLowerCase();
  add('timeline', TIMELINE_POINTS[timeline] ?? 0,
    timeline ? `timeline ${timeline}` : 'no timeline given');

  // Completeness is a genuine quality signal, not padding: a lead that answered
  // everything is measurably more likely to engage than one that gave a phone number.
  const present = [
    [lead.email_normalized, 'email'],
    [lead.phone_e164, 'phone'],
    [lead.company, 'company'],
    [String(lead.free_text_need ?? '').length >= 20 ? 'y' : '', 'described need'],
    [lead.country, 'country'],
  ].filter(([v]) => Boolean(v)).map(([, label]) => label);
  add('completeness', present.length * 2, `provided ${present.join(', ') || 'almost nothing'}`);

  const region = lead.region ?? enriched.region;
  add('region_served', SERVED_REGIONS.has(region) ? 10 : 0,
    region ? `region ${region}` : 'region unknown');

  add('strategic_account', enriched.strategic_account ? 15 : 0,
    enriched.strategic_account ? 'flagged strategic account' : 'not a strategic account');

  const raw = rules.reduce((n, r) => n + r.points, 0);
  const score = Math.max(0, Math.min(100, raw));
  if (raw > 100) rules.push({ rule_id: 'cap', points: 100 - raw, reason: `raw ${raw} capped to 100` });

  return {
    score,
    raw_score: raw,
    breakdown: rules,
    model_version: SCORE_MODEL_VERSION,
    band: bandFor(score),
    vip: score >= 90 || Boolean(enriched.strategic_account),
    vip_reason: score >= 90 ? 'score >= 90'
      : enriched.strategic_account ? 'strategic account flag' : null,
  };
}

function bandFor(score) {
  if (score >= 70) return 'qualified';
  if (score >= 40) return 'nurture';
  return 'unqualified';
}

const BAND_ORDER = ['unqualified', 'nurture', 'qualified'];
const AI_TO_BAND = { spam: 'unqualified', low_intent: 'unqualified', moderate: 'nurture', high_potential: 'qualified' };

// "Materially conflict" is undefined in the brief, so it is defined here: more than
// one band apart, and the model was confident. Adjacent disagreement is noise —
// treating it as conflict would send most of the funnel to manual review.
const CONFLICT_PREDICATE_VERSION = 'v1';

function detectConflict({ band, ai }) {
  if (!ai || !ai.label || ai.fallback_used) {
    return { conflict: false, reason: 'no usable AI classification', predicate_version: CONFLICT_PREDICATE_VERSION };
  }
  const aiBand = AI_TO_BAND[ai.label];
  if (!aiBand) {
    return { conflict: false, reason: `unmapped AI label ${ai.label}`, predicate_version: CONFLICT_PREDICATE_VERSION };
  }
  const distance = Math.abs(BAND_ORDER.indexOf(aiBand) - BAND_ORDER.indexOf(band));
  const confident = Number(ai.confidence ?? 0) >= 0.6;
  const conflict = distance > 1 && confident;
  return {
    conflict,
    distance,
    ai_band: aiBand,
    rule_band: band,
    confidence: ai.confidence ?? null,
    reason: conflict
      ? `AI says ${aiBand} at ${ai.confidence}, rules say ${band} — ${distance} bands apart`
      : `distance ${distance}, confidence ${ai.confidence ?? 'n/a'} — within tolerance`,
    predicate_version: CONFLICT_PREDICATE_VERSION,
  };
}
// ---- 09_Lib/dedup.mjs ---------------------------------------------------
// Who the person is, as opposed to where mail can be delivered. Dots and +tags are
// stripped for everyone here: this value is only ever compared, never sent to.
function identityLocal(email) {
  const { valid, localPart } = normalizeEmail(email);
  return valid ? localPart.split('+')[0].replace(/\./g, '') : null;
}

// Features are derived independently and weights are published, so a merge decision
// can be re-argued from its stored vector rather than taken on trust. The thresholds
// are priors, not fitted values — see the design note for why that is defensible.

const DEDUP_MODEL_VERSION = 'v1';

function jaroWinkler(a = '', b = '') {
  if (!a || !b) return 0;
  if (a === b) return 1;

  const window = Math.max(0, Math.floor(Math.max(a.length, b.length) / 2) - 1);
  const aMatched = new Array(a.length).fill(false);
  const bMatched = new Array(b.length).fill(false);
  let matches = 0;

  for (let i = 0; i < a.length; i++) {
    for (let j = Math.max(0, i - window); j < Math.min(b.length, i + window + 1); j++) {
      if (bMatched[j] || a[i] !== b[j]) continue;
      aMatched[i] = bMatched[j] = true;
      matches++;
      break;
    }
  }
  if (!matches) return 0;

  let transpositions = 0, k = 0;
  for (let i = 0; i < a.length; i++) {
    if (!aMatched[i]) continue;
    while (!bMatched[k]) k++;
    if (a[i] !== b[k]) transpositions++;
    k++;
  }
  transpositions /= 2;

  const jaro = (matches / a.length + matches / b.length + (matches - transpositions) / matches) / 3;
  let prefix = 0;
  while (prefix < 4 && prefix < a.length && prefix < b.length && a[prefix] === b[prefix]) prefix++;
  return jaro + prefix * 0.1 * (1 - jaro);
}

// Identity evidence says *who* this is. Circumstantial evidence only corroborates.
// The split matters: the circumstantial weights sum to 0.20, which is deliberately
// smaller than the 0.25 gap between the review and auto-merge thresholds. So timing
// and source can move a pair within a band but can never, on their own, carry it
// into an automatic merge. Change these numbers and that invariant is what breaks.
const IDENTITY_WEIGHTS = {
  email_local_match: 0.35,
  name_similarity: 0.25,
  company_match: 0.15,
};

const CIRCUMSTANTIAL_WEIGHTS = {
  temporal_proximity: 0.10,
  cross_source: 0.10,
};

const WEIGHTS = { ...IDENTITY_WEIGHTS, ...CIRCUMSTANTIAL_WEIGHTS };

function extractFeatures(candidate, existing) {
  const f = {};

  f.phone_exact = Boolean(candidate.phone_e164 && candidate.phone_e164 === existing.phone_e164);
  f.email_exact = Boolean(
    candidate.email_normalized && candidate.email_normalized === existing.email_normalized);

  const candKey = emailDedupKey(candidate.email_normalized ?? candidate.email_raw);
  const exisKey = emailDedupKey(existing.email_normalized ?? existing.email_raw);
  f.email_dedup_key_match = Boolean(candKey && candKey === exisKey);

  // Same local part on a different domain: the work-address / personal-address pair.
  // Compared via identityLocal rather than the dedup key, because the dedup key
  // only strips dots for providers that ignore them; which would make
  // luis.ferreira@work and luisferreira@gmail look like different people.
  const candLocal = identityLocal(candidate.email_normalized ?? candidate.email_raw);
  const exisLocal = identityLocal(existing.email_normalized ?? existing.email_raw);
  f.email_local_match = Boolean(candLocal && candLocal === exisLocal && !f.email_exact);

  const candName = candidate.name_normalized ?? normalizeName(candidate.full_name).normalized;
  const exisName = existing.name_normalized ?? normalizeName(existing.full_name).normalized;
  f.name_similarity = candName && exisName ? Number(jaroWinkler(candName, exisName).toFixed(3)) : 0;

  const candCo = normalizeCompany(candidate.company);
  const exisCo = normalizeCompany(existing.company);
  f.company_match = Boolean(candCo && exisCo && candCo === exisCo);

  const dtMs = Math.abs(
    new Date(candidate.ingested_at ?? Date.now()) - new Date(existing.ingested_at ?? Date.now()));
  f.hours_apart = Number((dtMs / 3_600_000).toFixed(2));
  f.temporal_proximity = f.hours_apart <= 24;

  // Cross-source *raises* suspicion rather than lowering it: edge case 1 is
  // specifically the same person arriving via WhatsApp and the website.
  f.cross_source = Boolean(candidate.source && existing.source && candidate.source !== existing.source);

  // Explicit disagreement, used to demote an otherwise decisive match. A shared
  // office line is real, and a rule that merges on phone alone will eventually
  // merge two different people.
  f.email_conflict = Boolean(
    candidate.email_normalized && existing.email_normalized &&
    candidate.email_normalized !== existing.email_normalized && !f.email_local_match);
  f.name_conflict = Boolean(candName && exisName && f.name_similarity < 0.70);

  return f;
}

function scoreCandidate(candidate, existing) {
  const f = extractFeatures(candidate, existing);
  const decisive = f.phone_exact || f.email_exact || f.email_dedup_key_match;

  let confidence;
  const contributions = [];

  if (decisive) {
    confidence = 0.95;
    contributions.push({
      feature: f.email_exact ? 'email_exact' : f.phone_exact ? 'phone_exact' : 'email_dedup_key_match',
      contribution: 0.95,
      note: 'decisive identifier match',
    });
  } else {
    confidence = 0;
    for (const [key, weight] of Object.entries(WEIGHTS)) {
      const value = key === 'name_similarity' ? f.name_similarity : (f[key] ? 1 : 0);
      const points = weight * value;
      if (points > 0) contributions.push({ feature: key, contribution: Number(points.toFixed(3)) });
      confidence += points;
    }
  }

  // Demotion, not rejection: contradicted evidence moves the pair to a human
  // rather than deciding it either way.
  const contradictions = [];
  if (decisive && f.email_conflict) contradictions.push('different email address');
  if (decisive && f.name_conflict) contradictions.push('names do not match');
  if (contradictions.length) {
    confidence = Math.min(confidence, 0.80);
    contributions.push({ feature: 'contradiction_demotion', contribution: -0.15, note: contradictions.join('; ') });
  }

  return {
    candidate_lead_id: existing.lead_id,
    confidence: Number(Math.max(0, Math.min(1, confidence)).toFixed(3)),
    decisive,
    contradictions,
    features: f,
    contributions,
    model_version: DEDUP_MODEL_VERSION,
  };
}

function tierFor(confidence, { autoMerge = 0.90, review = 0.65 } = {}) {
  if (confidence >= autoMerge) return 'auto_merge';
  if (confidence >= review) return 'review';
  return 'distinct';
}

function assess(candidate, existingRecords, thresholds) {
  const scored = existingRecords
    .filter((e) => e.lead_id !== candidate.lead_id)
    .map((e) => scoreCandidate(candidate, e))
    .sort((a, b) => b.confidence - a.confidence);

  const best = scored[0] ?? null;
  const tier = best ? tierFor(best.confidence, thresholds) : 'distinct';

  return {
    tier,
    best,
    // Retained in full so thresholds can be fitted from outcomes later.
    all: scored,
    // Ties broken by ULID: the earlier-arriving record becomes the master, which
    // keeps merges deterministic regardless of evaluation order.
    master_lead_id: best && tier !== 'distinct'
      ? [candidate.lead_id, best.candidate_lead_id].sort()[0]
      : candidate.lead_id,
  };
}
// ---- 09_Lib/routing.mjs -------------------------------------------------
// Where a lead goes, who owns it, and what must not happen automatically.
//
// The governing rule for holds: gate the irreversible, not the reversible. Scoring
// and enrichment can always be redone, so a probable duplicate keeps moving through
// them. Creating a CRM record or messaging a human cannot be undone, so those wait.

const ROUTING_VERSION = 'v1';

function route({ lead, scored, conflict, dedup }) {
  const holds = [];
  let disposition;
  let reason;

  const tier = dedup?.tier ?? 'distinct';

  if (lead.disposition === 'data_completion') {
    disposition = 'data_completion';
    reason = lead.status_reason || 'critical contact data missing';
    holds.push({ what: 'outbound', why: 'lead has no reachable channel' });
  } else if (tier === 'auto_merge' && dedup.master_lead_id !== lead.lead_id) {
    // This record loses to an earlier one. It stops here; the master carries on.
    disposition = 'merged';
    reason = `folded into ${dedup.master_lead_id} at confidence ${dedup.best?.confidence}`;
    holds.push({ what: 'outbound', why: 'superseded by master record' });
    holds.push({ what: 'crm', why: 'superseded by master record' });
  } else if (conflict?.conflict) {
    disposition = 'manual_review';
    reason = conflict.reason;
  } else {
    disposition = scored.band;
    reason = `score ${scored.score} in band ${scored.band} under model ${scored.model_version}`;
  }

  if (tier === 'review' && disposition !== 'merged') {
    // Keep processing, but nothing irreversible until a human rules on it.
    holds.push({ what: 'crm', why: 'possible duplicate awaiting review' });
    holds.push({ what: 'outbound', why: 'possible duplicate awaiting review' });
  }

  const vip = Boolean(scored.vip) && disposition !== 'merged';
  if (vip) {
    // A transactional acknowledgement is not a sales action, so it is not held here.
    // Only sales outreach waits on the manager.
    holds.push({ what: 'sales_outreach', why: scored.vip_reason || 'VIP requires manager approval' });
  }

  if (lead.consent_status === 'denied' || lead.consent_status === 'withdrawn') {
    holds.push({ what: 'outbound', why: `consent ${lead.consent_status}` });
  }

  return {
    disposition,
    reason,
    vip,
    vip_reason: vip ? (scored.vip_reason ?? null) : null,
    approval_required: vip,
    holds,
    hold_outbound: holds.some((h) => h.what === 'outbound'),
    hold_crm: holds.some((h) => h.what === 'crm'),
    hold_sales_outreach: holds.some((h) => h.what === 'sales_outreach' || h.what === 'outbound'),
    assignable: disposition === 'qualified' || disposition === 'nurture',
    routing_version: ROUTING_VERSION,
  };
}

const loadRatio = (rep) => rep.open_leads / Math.max(rep.capacity, 1);

// Fallback ladder, most specific first. Each rung is recorded, so assignment_reason
// says not just who got the lead but how far we had to reach to find them.
const LADDER = [
  { level: 'category_and_region', match: (r, l) => matchesCategory(r, l) && matchesRegion(r, l) },
  { level: 'category_only',       match: (r, l) => matchesCategory(r, l) },
  { level: 'region_only',         match: (r, l) => matchesRegion(r, l) },
  { level: 'any_available',       match: () => true },
];

const matchesCategory = (rep, lead) =>
  !lead.service_interest || (rep.service_categories ?? []).includes(lead.service_interest);

const matchesRegion = (rep, lead) => {
  const region = lead.region ?? lead.enrichment?.data?.region;
  return !region || (rep.regions ?? []).includes(region);
};

function assignRep({ lead, reps, overloadThreshold = 1 }) {
  // Availability and spare capacity are checked at assignment time, not read from a
  // stale snapshot. Edge case 9 is the same check happening again at dispatch.
  const eligible = (reps ?? []).filter((r) => r.available && loadRatio(r) < overloadThreshold);

  if (!eligible.length) {
    const anyAvailable = (reps ?? []).filter((r) => r.available);
    if (!anyAvailable.length) {
      return { rep_id: null, reason: 'no available rep — escalating to manager', fallback_level: 'none', escalate: true };
    }
    // Everyone is at or over capacity: give it to the least-loaded rather than
    // dropping it, and flag that the team is saturated.
    const least = [...anyAvailable].sort((a, b) => loadRatio(a) - loadRatio(b))[0];
    return {
      rep_id: least.rep_id,
      reason: `all reps at capacity; assigned least-loaded (${least.open_leads}/${least.capacity})`,
      fallback_level: 'over_capacity',
      escalate: true,
    };
  }

  for (const rung of LADDER) {
    const pool = eligible.filter((r) => rung.match(r, lead));
    if (!pool.length) continue;
    const pick = [...pool].sort((a, b) => loadRatio(a) - loadRatio(b) || a.rep_id.localeCompare(b.rep_id))[0];
    return {
      rep_id: pick.rep_id,
      reason: `${rung.level}: ${pick.rep_id} at ${pick.open_leads}/${pick.capacity}`,
      fallback_level: rung.level,
      escalate: false,
    };
  }

  return { rep_id: null, reason: 'no rep matched any fallback rung', fallback_level: 'none', escalate: true };
}
// ---- 09_Lib/odoo.mjs ----------------------------------------------------
// Funnel stages, ranked. The rank is what lets a single writer refuse to move a
// lead backwards: stage changes are driven from qualification, follow-up, booking,
// manager rejection and SLA escalation, and without ordering protection a slow
// writer can regress a lead that has already progressed.
//
// This guard also lives in the mock, but that is an assertion aid. Real Odoo will
// happily write whatever stage you send it, so the guard has to be here.

const STAGE_RANK = {
  new: 10,
  contacted: 20,
  qualified: 30,
  proposition: 40,
  meeting_booked: 50,
  won: 100,
  lost: 100,
};

const DISPOSITION_STAGE = {
  data_completion: 'new',
  manual_review: 'contacted',
  nurture: 'contacted',
  qualified: 'qualified',
  unqualified: 'lost',
  merged: null,        // the master carries the funnel; the loser has no stage of its own
};

function stageForDisposition(disposition) {
  return DISPOSITION_STAGE[disposition] ?? null;
}

function rankOf(stage) {
  return STAGE_RANK[stage] ?? null;
}

// Returns what the writer should do, and why, rather than a bare boolean — the
// reason ends up in the audit trail.
function planStageTransition({ current, target, rollbackReason = null }) {
  if (!target) return { action: 'skip', reason: 'no stage implied by this disposition' };

  const targetRank = rankOf(target);
  if (targetRank === null) return { action: 'reject', reason: `unknown stage "${target}"` };

  if (!current) return { action: 'set', reason: `initial stage ${target}`, rank: targetRank };
  if (current === target) return { action: 'skip', reason: `already in ${target}` };

  const currentRank = rankOf(current) ?? 0;
  if (targetRank > currentRank) {
    return { action: 'set', reason: `advance ${current} -> ${target}`, rank: targetRank };
  }

  if (rollbackReason) {
    return { action: 'rollback', reason: `deliberate rollback ${current} -> ${target}: ${rollbackReason}`, rank: targetRank };
  }

  return {
    action: 'refuse',
    reason: `refused regression ${current} (${currentRank}) -> ${target} (${targetRank}); supply a rollback reason to force it`,
    rank: targetRank,
  };
}
// ---- 09_Lib/followup.mjs ------------------------------------------------
// Follow-up sequences, SLA and approval expiry are the same mechanism: do X at time
// T, revalidating state at T. An n8n Wait node cannot be cancelled or signalled from
// outside, so a scheduled follow-up would be uncancellable and would not survive a
// restart. The wait therefore lives in a table and the decision is made at dispatch.

// Qualified leads get chased quickly and briefly. Nurture leads get a long, sparse
// sequence — different cadence, not just different copy (brief section G).
const SEQUENCES = {
  qualified: [
    { step: 1, after_minutes: 60,     slot: 'followup.1', note: 'same-day nudge' },
    { step: 2, after_minutes: 1440,   slot: 'followup.2', note: 'next-day follow-up' },
    { step: 3, after_minutes: 4320,   slot: 'followup.3', note: 'final attempt at 72h' },
  ],
  nurture: [
    { step: 1, after_minutes: 4320,   slot: 'followup.1', note: '3-day check-in' },
    { step: 2, after_minutes: 14400,  slot: 'followup.2', note: '10-day value touch' },
    { step: 3, after_minutes: 43200,  slot: 'followup.3', note: '30-day re-engage' },
  ],
};

// Demo compression. Real cadence is measured in hours and days, which no reviewer is
// going to sit through, so the scale factor shortens every interval uniformly without
// changing the sequence being demonstrated.
function scaleMinutes(minutes, scale = 1) {
  const s = Number(scale);
  const factor = Number.isFinite(s) && s > 0 ? s : 1;
  return Math.max(1 / 60, minutes * factor);
}

function nextStep({ disposition, currentStep = 0 }) {
  const seq = SEQUENCES[disposition];
  if (!seq) return null;
  return seq.find((s) => s.step === currentStep + 1) ?? null;
}

// Reasons a sequence stops for good. Checked at dispatch rather than at schedule
// time, because every one of these can become true while the work is still queued.
function sequenceStopReason(lead, { booking = null } = {}) {
  if (!lead) return 'lead no longer exists';
  if (lead.consent_status === 'withdrawn' || lead.consent_status === 'denied') {
    return `consent ${lead.consent_status}`;
  }
  if (lead.dedup_status === 'merged_into') return 'lead merged into another record';
  if (booking || lead.status === 'meeting_booked') return 'meeting booked';
  if (lead.status === 'closed' || lead.status === 'won' || lead.status === 'lost') {
    return `lead ${lead.status}`;
  }
  if (lead.status === 'replied') return 'lead replied';
  if (lead.approval_state === 'rejected') return 'VIP rejected by manager';
  if (!['qualified', 'nurture'].includes(lead.disposition)) {
    return `disposition is ${lead.disposition}`;
  }
  return null;
}

// SLA is measured from assignment to the first logged sales action. Viewing a record
// is not an action; the definition is deliberately narrow, because a broad one makes
// the SLA unenforceable.
function slaBreached(lead, { slaMinutes = 30, now = Date.now() } = {}) {
  if (lead.disposition !== 'qualified') return { breached: false, reason: 'not a qualified lead' };
  if (lead.last_sales_action_at) return { breached: false, reason: 'sales action already logged' };
  if (!lead.assigned_at) return { breached: false, reason: 'never assigned' };

  const elapsed = (now - new Date(lead.assigned_at).getTime()) / 60000;
  return {
    breached: elapsed >= slaMinutes,
    elapsed_minutes: Math.round(elapsed),
    threshold_minutes: slaMinutes,
    reason: elapsed >= slaMinutes
      ? `no sales action ${Math.round(elapsed)} minutes after assignment`
      : `within SLA (${Math.round(elapsed)} of ${slaMinutes} minutes)`,
  };
}

// What to do when a manager never answers a VIP approval. This is risk appetite, not
// engineering: sending unapproved risks an unwanted message to a strategic account,
// holding risks silence on the highest-value lead in the funnel. Configurable, and
// the default is the cautious one.
const APPROVAL_TIMEOUT_POLICIES = ['escalate', 'send', 'hold'];

function approvalTimeoutAction(policy = 'escalate') {
  switch (policy) {
    case 'send':
      return { action: 'release', reason: 'fail-open: timeout treated as approval' };
    case 'hold':
      return { action: 'hold', reason: 'fail-closed: outreach stays blocked until a human acts' };
    case 'escalate':
    default:
      return { action: 'escalate', reason: 'fail-closed with escalation to a second approver' };
  }
}
/* __END_LEADOPS_LIB__ */

// Keyed on the provider's booking id, never on our receipt of it. A webhook
// delivered twice therefore applies once (edge case 11).

const b = $input.first().json.body ?? {};
const bookingId = b.booking_id ?? b.id;
const leadId = b.lead_id;

if (!bookingId || !leadId) {
  return [{ json: { reject: true, error: 'booking_id and lead_id are required',
    workflow: $workflow.name, execution_id: $execution.id } }];
}

const key = effectKey({ domain: 'booking.apply', entityType: 'booking', entityId: bookingId });

return [{ json: {
  key,
  lead_id: leadId,
  source: 'booking',
  provider_event_id: bookingId,
  event: b,
  // A booked meeting is a sales action and a funnel advance in one.
  lead_patch: { status: 'meeting_booked', sales_action: true,
                status_reason: 'meeting booked ' + (b.starts_at ?? '') },
  // Marketing follow-up stops the moment a meeting exists.
  cancel_kinds: ['followup', 'sla_check'],
  cancel_reason: 'meeting booked',
  enqueue: [
    { kind: 'odoo_sync',
      payload: { action: 'stage', stage: 'meeting_booked', reason: 'booking confirmed' },
      idempotency_key: effectKey({ domain: 'odoo.stage.set', entityId: leadId, occurrence: 'meeting_booked' }) },
    { kind: 'outbound',
      payload: { slot: 'rep_booking_notice', channel: 'email', to: b.rep_email ?? null,
                 lead_ref: leadId, booking_id: bookingId },
      idempotency_key: effectKey({ domain: 'msg.send', entityId: leadId, occurrence: 'booking.notice' }) },
  ],
  events: [
    { step: 'booking', event_type: 'booking.applied', decision: 'meeting_booked',
      inputs: { booking_id: bookingId, starts_at: b.starts_at ?? null },
      outputs: { stopped: ['followup', 'sla_check'], notified: 'assigned rep' } },
  ],
  workflow: $workflow.name,
  execution_id: $execution.id,
} }];

const r = $input.first().json;
return [{ json: {
  received: true,
  applied: r.applied > 0,
  duplicate_delivery: r.applied === 0,
  work_cancelled: r.work_cancelled ?? 0,
  enqueued: r.enqueued ?? 0,
} }];
